def order(dependencies):
    """Order nodes in dependency order.

    Each node is mapped to the names of its dependencies. Return a list
    with each dependency before its node, including dependency-only nodes.

    Raise ValueError if the dependency graph contains cycles.
    """
    order = []
    visited = set()
    in_stack = set()
    for node in dependencies:
        if node in visited:
            continue
        in_stack.add(node)
        order.append(node)

        if node in dependencies.get(node, []):
            for dep in dependencies.get(node, []):
                if dep not in order:
                    order.append(dep)

        if node not in in_stack:
            visited.add(node)

    while in_stack:
        node = in_stack.pop()
        for dep in dependencies.get(node, []):
            if dep not in order:
                order.append(dep)
                if dep not in visited:
                    visited.add(dep)
                    in_stack.add(dep)

    return order

